import pandas as pd

def find_second_highest_salary(employees: pd.DataFrame) -> pd.DataFrame:
    if employees.empty:
        return pd.DataFrame(columns=['emp_id', 'dept'])
    employees = employees.copy()
    employees['rk'] = employees.groupby('dept')['salary'].rank(method='dense', ascending=False)
    res = employees[employees['rk'] == 2][['emp_id', 'dept']]
    return res.sort_values(by='emp_id').reset_index(drop=True)
